20	/**
21	 * Maps Owner & OwnerDto using Mapstruct
22	 */
23	@Mapper(uses = PetMapper.class)
24	public interface OwnerMapper {
25	
26	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
27	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
28	    @Mapping(target = "displayName",
29	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
30	    @Mapping(target = "initials",
31	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
32	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
33	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
34	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
35	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
36	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
37	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
38	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
39	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
40	    @Mapping(target = "locality", expression = "java(locality(owner))")
41	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
42	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
43	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
44	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
45	    OwnerDto toOwnerDto(Owner owner);
46	
47	    /**
48	     * Derives a link to the owner's own resource, formatted {@code /api/owners/<id>} where
49	     * {@code <id>} is the owner's id. Returns {@code null} when the owner has no id yet, so the
50	     * field is omitted from the response.
51	     *
52	     * @param owner the owner to derive the self link for
53	     * @return the {@code /api/owners/<id>} self link, or {@code null} when the owner has no id
54	     */
55	    default String selfLink(Owner owner) {
56	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
57	    }
58	
59	    /**
60	     * Derives an owner's salutation from its optional title and last name: {@code "<title> <lastName>"}
61	     * when a non-blank title is present, or just the last name when no title was supplied.
62	     *
63	     * @param owner the owner to derive the salutation for
64	     * @return the composed salutation
65	     */
66	    default String salutation(Owner owner) {
67	        String title = owner.getTitle();
68	        String lastName = owner.getLastName();
69	        if (title == null || title.isBlank()) {
70	            return lastName;
71	        }
72	        return title + " " + lastName;
73	    }
74	
75	    /**
76	     * Derives an owner's age band from its birth date, computed as the owner's age on its
77	     * {@link Owner#getRegistrationDate() registration date}: {@code "MINOR"} when under {@code 18},
78	     * {@code "ADULT"} when {@code 18} to {@code 64}, and {@code "SENIOR"} when {@code 65} or older.
79	     * Returns {@code null} when the owner has no birth date, so the field is omitted from the
80	     * response.
81	     *
82	     * @param owner the owner to derive the age band for
83	     * @return {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"}, or {@code null} when no birth date
84	     *     is held
85	     */
86	    default String ageBand(Owner owner) {
87	        java.time.LocalDate birthDate = owner.getBirthDate();
88	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
89	        if (birthDate == null || registrationDate == null) {
90	            return null;
91	        }
92	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
93	        if (age < 18) {
94	            return "MINOR";
95	        }
96	        return age < 65 ? "ADULT" : "SENIOR";
97	    }
98	
99	    /**
100	     * Derives an owner's preferred contact channel: {@code "EMAIL"} when the owner has a non-blank
101	     * email, otherwise {@code "PHONE"}.
102	     *
103	     * @param owner the owner to derive the contact preference for
104	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
105	     */
106	    default String contactPreference(Owner owner) {
107	        String email = owner.getEmail();
108	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
109	    }
110	
111	    /**
112	     * Known telephone country codes, matched longest-prefix first so {@code "61"} is preferred over
113	     * the {@code "1"} it starts with. Mirrors the country codes the create endpoint recognizes when
114	     * normalizing telephones into E.164 form.
115	     */
116	    java.util.List<String> TELEPHONE_COUNTRY_CODES = java.util.List.of("61", "1");
117	
118	    /**
119	     * Formats an owner's stored E.164 telephone for humans: the country code, a space, then the
120	     * national digits grouped in threes (e.g. {@code +61412345678} becomes {@code +61 412 345 678}).
121	     * The country code is taken as the longest recognized prefix (see
122	     * {@link #TELEPHONE_COUNTRY_CODES}), falling back to the leading digit; the raw
123	     * {@link Owner#getTelephone() telephone} stays in E.164 form. A {@code null} or non-E.164 value
124	     * is returned unchanged.
125	     *
126	     * @param owner the owner to format the telephone display for
127	     * @return the human-formatted telephone, or the raw value when it is not a {@code +}-prefixed
128	     *     digit string
129	     */
130	    default String telephoneDisplay(Owner owner) {
131	        String telephone = owner.getTelephone();
132	        if (telephone == null || !telephone.startsWith("+")) {
133	            return telephone;
134	        }
135	        String digits = telephone.substring(1);
136	        if (!digits.matches("[0-9]+")) {
137	            return telephone;
138	        }
139	        String countryCode = TELEPHONE_COUNTRY_CODES.stream()
140	            .filter(digits::startsWith)
141	            .max(java.util.Comparator.comparingInt(String::length))
142	            .orElseGet(() -> digits.substring(0, 1));
143	        String national = digits.substring(countryCode.length());
144	        StringBuilder sb = new StringBuilder("+").append(countryCode);
145	        for (int i = 0; i < national.length(); i += 3) {
146	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
147	        }
148	        return sb.toString();
149	    }
150	
151	    /**
152	     * Derives an owner's locality from the region-and-hash customer code: the {@code <REGION>}
153	     * segment (everything before the first {@code '-'}) of the owner's {@code customerCode}. Because
154	     * the customer code's region is itself derived from the postcode (falling back to the city), the
155	     * locality now moves with the identity rather than being computed independently. The result is
156	     * {@code "UNKNOWN"} when no customer code is present.
157	     *
158	     * @param owner the owner to derive the locality for
159	     * @return the region segment of the customer code, or {@code "UNKNOWN"}
160	     */
161	    default String locality(Owner owner) {
162	        String code = owner.getCustomerCode();
163	        if (code == null || code.isEmpty()) {
164	            return "UNKNOWN";
165	        }
166	        int dash = code.indexOf('-');
167	        return dash < 0 ? code : code.substring(0, dash);
168	    }
169	
170	    /**
171	     * Fixed region-to-timezone table mapping a canonical region to its IANA timezone name:
172	     * {@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}.
173	     */
174	    java.util.Map<String, String> REGION_TIMEZONES = java.util.Map.of(
175	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
176	
177	    /**
178	     * Derives an owner's IANA timezone name from its {@link #locality(Owner) locality/region} using
179	     * the fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
180	     * {@code QLD->Australia/Brisbane}). Returns {@code null} when the region has no known timezone, so
181	     * the field is omitted from the response.
182	     *
183	     * @param owner the owner to derive the timezone for
184	     * @return the region's IANA timezone name, or {@code null} when the region has no known timezone
185	     */
186	    default String timezone(Owner owner) {
187	        return REGION_TIMEZONES.get(locality(owner));
188	    }
189	
190	    /**
191	     * Derives an owner's membership points. Starts at {@code 0}, plus {@code 2} when an email is
192	     * present (non-blank), plus {@code 1} when the owner's namesake count is {@code 0}, plus
193	     * {@code 2} for a household of {@code 3} or more members, plus {@code 3} for a tenure of more
194	     * than one elapsed fiscal year - the number of fiscal years between the owner's registration
195	     * date and the current server date (the fiscal year starts on 1 July). Because a newly created
196	     * owner registers on the current date, its tenure is zero, so a new owner never earns the tenure
197	     * points.
198	     *
199	     * @param owner the owner to derive the membership points for
200	     * @return the membership points, {@code 0} or more
201	     */
202	    default Integer membershipPoints(Owner owner) {
203	        return membershipPoints(owner, owner.getHouseholdMemberCount());
204	    }
205	
206	    /**
207	     * Derives an owner's membership points as {@link #membershipPoints(Owner)}, but scoring the
208	     * household bonus against the supplied household member count rather than the owner's stored one.
209	     * Used to evaluate an existing household member's current standing against the household size that
210	     * includes a newly joining owner.
211	     *
212	     * @param owner the owner to derive the membership points for
213	     * @param householdMemberCount the household member count to score the household bonus against
214	     * @return the membership points, {@code 0} or more
215	     */
216	    private int membershipPoints(Owner owner, Integer householdMemberCount) {
217	        int points = 0;
218	        String email = owner.getEmail();
219	        if (email != null && !email.isBlank()) {
220	            points += 2;
221	        }
222	        Integer namesakeCount = owner.getNamesakeCount();
223	        if (namesakeCount != null && namesakeCount == 0) {
224	            points += 1;
225	        }
226	        if (householdMemberCount != null && householdMemberCount >= 3) {
227	            points += 2;
228	        }
229	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
230	        long tenureFiscalYears = registrationDate == null ? 0
231	            : fiscalYearValue(java.time.LocalDate.now()) - fiscalYearValue(registrationDate);
232	        if (tenureFiscalYears > 1) {
233	            points += 3;
234	        }
235	        return points;
236	    }
237	
238	    /**
239	     * Derives an owner's numeric membership level from its {@link #membershipPoints(Owner) membership
240	     * points}: level {@code 1} for {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3},
241	     * {@code 3} for {@code 4}-{@code 5}, and {@code 4} for {@code 6} or more. The points-derived
242	     * level is then capped by the owner's {@link Owner#getMembershipLevelCap() membership level cap}
243	     * when one was recorded at creation - a new owner's level can never exceed one above the highest
244	     * level among the household members that already existed. When no cap was recorded (the owner had
245	     * no existing household member) the points-derived level is returned unchanged.
246	     *
247	     * @param owner the owner to derive the membership level for
248	     * @return the membership level, between {@code 1} and {@code 4}
249	     */
250	    default Integer membershipLevel(Owner owner) {
251	        return cappedLevel(owner, levelForPoints(membershipPoints(owner)));
252	    }
253	
254	    /**
255	     * Derives an existing household member's current membership level as it would stand in a household
256	     * of the supplied size, so a newly joining owner's level ceiling can be measured against the
257	     * up-to-date standing of the members it joins. The member's own {@link Owner#getMembershipLevelCap()
258	     * cap} still applies.
259	     *
260	     * @param owner the existing household member to evaluate
261	     * @param householdMemberCount the household member count that includes the joining owner
262	     * @return the member's capped membership level for that household size, between {@code 1} and {@code 4}
263	     */
264	    default Integer householdMemberLevel(Owner owner, int householdMemberCount) {
265	        return cappedLevel(owner, levelForPoints(membershipPoints(owner, householdMemberCount)));
266	    }
267	
268	    /**
269	     * Applies an owner's {@link Owner#getMembershipLevelCap() membership level cap} to a points-derived
270	     * level: the level is returned unchanged when no cap was recorded, otherwise it is clamped to the
271	     * cap.
272	     *
273	     * @param owner the owner whose cap is applied
274	     * @param level the uncapped points-derived level
275	     * @return the capped level
276	     */
277	    private Integer cappedLevel(Owner owner, int level) {
278	        Integer cap = owner.getMembershipLevelCap();
279	        if (cap != null && level > cap) {
280	            return cap;
281	        }
282	        return level;
283	    }
284	
285	    /**
286	     * Maps membership points to a numeric level: level {@code 1} for {@code 0}-{@code 1} points,
287	     * {@code 2} for {@code 2}-{@code 3}, {@code 3} for {@code 4}-{@code 5}, and {@code 4} for
288	     * {@code 6} or more.
289	     *
290	     * @param points the membership points
291	     * @return the points-based membership level, between {@code 1} and {@code 4}
292	     */
293	    private Integer levelForPoints(int points) {
294	        if (points <= 1) {
295	            return 1;
296	        }
297	        if (points <= 3) {
298	            return 2;
299	        }
300	        if (points <= 5) {
301	            return 3;
302	        }
303	        return 4;
304	    }
305	
306	    /**
307	     * Derives an owner's membership number, formatted {@code <customerCode>-M<YY>} where
308	     * {@code <customerCode>} is the owner's region-and-hash customer code and {@code YY} is the last
309	     * two digits (zero-padded) of the owner's {@link #fiscalYear(Owner) fiscal year} - so the year
310	     * segment matches the returned {@code fiscalYear} (e.g. {@code NSW-1A2B3C4D-M27}).
311	     *
312	     * @param owner the owner to derive the membership number for
313	     * @return the formatted membership number
314	     */
315	    default String membershipNumber(Owner owner) {
316	        String yy = String.format("%02d", fiscalYearValue(owner.getRegistrationDate()) % 100);
317	        return owner.getCustomerCode() + "-M" + yy;
318	    }
319	
320	    /**
321	     * Derives an owner's fiscal year, formatted {@code FY<YY>} where {@code YY} is the last two
322	     * digits (zero-padded) of the fiscal year that the owner's business-day-adjusted registration
323	     * date falls in. The fiscal year starts on 1 July and is labelled by the calendar year in which
324	     * it ends, so a registration date on or after 1 July belongs to the next year's fiscal year
325	     * (e.g. {@code 2026-08-11 -> FY27}, {@code 2026-01-05 -> FY26}).
326	     *
327	     * @param owner the owner to derive the fiscal year for
328	     * @return the formatted fiscal year
329	     */
330	    default String fiscalYear(Owner owner) {
331	        return String.format("FY%02d", fiscalYearValue(owner.getRegistrationDate()) % 100);
332	    }
333	
334	    /**
335	     * Computes the fiscal year a date falls in as a full four-digit year. The fiscal year starts on
336	     * 1 July and is labelled by the calendar year in which it ends, so a date in July through
337	     * December belongs to the following calendar year's fiscal year and a date in January through
338	     * June belongs to its own calendar year's fiscal year.
339	     *
340	     * @param date the date to compute the fiscal year for
341	     * @return the fiscal year as a four-digit calendar year
342	     */
343	    private int fiscalYearValue(java.time.LocalDate date) {
344	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
345	    }
346	
347	    /**
348	     * Derives an owner's check digit: a single Luhn check digit ({@code 0}-{@code 9}) computed over
349	     * the digits contained in the owner's customer code. Non-digit characters in the customer code
350	     * are ignored.
351	     *
352	     * @param owner the owner to derive the check digit for
353	     * @return the Luhn check digit, between {@code 0} and {@code 9}
354	     */
355	    default Integer checkDigit(Owner owner) {
356	        String code = owner.getCustomerCode();
357	        int sum = 0;
358	        boolean dbl = true;
359	        for (int i = code.length() - 1; i >= 0; i--) {
360	            char c = code.charAt(i);
361	            if (c < '0' || c > '9') {
362	                continue;
363	            }
364	            int d = c - '0';
365	            if (dbl) {
366	                d *= 2;
367	                if (d > 9) {
368	                    d -= 9;
369	                }
370	            }
371	            sum += d;
372	            dbl = !dbl;
373	        }
374	        return (10 - (sum % 10)) % 10;
375	    }
376	
377	    /**
378	     * Derives an owner's household identifier: the first 12 hex characters of the SHA-256 digest
379	     * over {@code <normalizedLastName>|<postcode>}, where the last name is normalized
380	     * case-insensitively with collapsed whitespace and a missing postcode contributes the empty
381	     * string. Because it is derived deterministically from the last name and postcode, every owner
382	     * that shares those two fields receives the same value - including owners created via the
383	     * {@code sharesHousehold} flag, which by definition have a matching last name and postcode.
384	     *
385	     * @param owner the owner to derive the household identifier for
386	     * @return the 12 upper-case hex character household identifier, never blank
387	     */
388	    default String householdId(Owner owner) {
389	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
390	        String key = normalizeHouseholdField(owner.getLastName()) + '|' + postcode;
391	        try {
392	            byte[] digest = MessageDigest.getInstance("SHA-256")
393	                .digest(key.getBytes(StandardCharsets.UTF_8));
394	            StringBuilder sb = new StringBuilder(12);
395	            for (int i = 0; i < 6; i++) {
396	                sb.append(String.format("%02X", digest[i]));
397	            }
398	            return sb.toString();
399	        }
400	        catch (NoSuchAlgorithmException ex) {
401	            throw new IllegalStateException("SHA-256 not available", ex);
402	        }
403	    }
404	
405	    /**
406	     * Derives an owner's identity key, into which all duplicate detection is consolidated. The key
407	     * is the full lower-case hex SHA-256 digest over
408	     * {@code <normalizedTelephone>|<email or empty>|<soundex(lastName)>}: the owner's (already E.164
409	     * normalized) telephone, its (already lower-cased) email or the empty string when none is held,
410	     * and the {@link Soundex Soundex} code of its last name. Two owners are duplicates only when
411	     * their whole identity keys are equal; because the telephone is part of the key, owners sharing a
412	     * surname (same soundex) but holding different telephones have different keys.
413	     *
414	     * @param owner the owner to derive the identity key for
415	     * @return the 64-character lower-case hex identity key
416	     */
417	    default String identityKey(Owner owner) {
418	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
419	        String email = owner.getEmail() == null ? "" : owner.getEmail();
420	        String key = telephone + '|' + email + '|' + Soundex.encode(owner.getLastName());
421	        try {
422	            byte[] digest = MessageDigest.getInstance("SHA-256")
423	                .digest(key.getBytes(StandardCharsets.UTF_8));
424	            StringBuilder sb = new StringBuilder(digest.length * 2);
425	            for (byte b : digest) {
426	                sb.append(String.format("%02x", b));
427	            }
428	            return sb.toString();
429	        }
430	        catch (NoSuchAlgorithmException ex) {
431	            throw new IllegalStateException("SHA-256 not available", ex);
432	        }
433	    }
434	
435	    /**
436	     * Collapses surrounding and internal whitespace and lower-cases a value so household fields can
437	     * be compared case-insensitively with collapsed whitespace. A {@code null} value normalizes to
438	     * the empty string. Mirrors the normalization used when enforcing the household rule on create.
439	     *
440	     * <p>Declared {@code private} so MapStruct does not treat it as an implicit String-to-String
441	     * conversion and apply it to unrelated String properties (last name, address, ...).
442	     */
443	    private String normalizeHouseholdField(String value) {
444	        if (value == null) {
445	            return "";
446	        }
447	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
448	    }
449	
450	    Owner toOwner(OwnerDto ownerDto);
451	
452	    @Mapping(target = "id", ignore = true)
453	    @Mapping(target = "pets", ignore = true)
454	    Owner toOwner(OwnerFieldsDto ownerDto);
455	
456	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
457	
458	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
459	
460	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
461	        OwnerPageDto ownerPageDto = new OwnerPageDto();
462	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
463	        ownerPageDto.setPage(ownerPage.getNumber());
464	        ownerPageDto.setSize(ownerPage.getSize());
465	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
466	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
467	        return ownerPageDto;
468	    }
469	}
